import { deliveryFromEnv, type EmailEnv } from "@rallypoint/email/client";
import { drainEmail } from "@rallypoint/email/drain";
// @ts-expect-error: generated by `opennextjs-cloudflare build`; it has no types and does not exist before a build.
import handler from "./.open-next/worker.js";

// Minimal shapes of the Workers runtime objects this entry uses.
interface ScheduledController {
  readonly cron: string;
  readonly scheduledTime: number;
}
interface ExecutionContext {
  waitUntil(promise: Promise<unknown>): void;
}

async function run(env: EmailEnv): Promise<void> {
  try {
    const options = deliveryFromEnv(env);
    if (options) {
      try {
        await drainEmail(options);
      } finally {
        await options.close();
      }
    }
  } catch {
    // Never log the error: it can carry provider or database detail.
    console.error("email drain failed");
  }
}

export default {
  fetch: handler.fetch,
  async scheduled(
    _controller: ScheduledController,
    env: EmailEnv,
    ctx: ExecutionContext,
  ): Promise<void> {
    ctx.waitUntil(run(env));
  },
};
